Let’s get you something usable. Magic Hour is still blocking generation with “Should any words appear on it? If so, which, exactly?”—even though you’ve answered.

**Here’s a self-contained alternative that makes all five slides as 1080 × 1350 PNGs**, with your exact wording, blue-and-white styling, and matching illustrations. No cover or closing slide.

Save the code below as **`focus-carousel.html`**, open it in your browser, and click the download button beneath each slide. No account or additional tools needed.

```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<title>Focus carousel</title>
<style>
  * { box-sizing: border-box }
  body {
    margin: 0; padding: 32px;
    background: #eaf0f8;
    font-family: Arial, sans-serif;
  }
  main {
    max-width: 1100px; margin: auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 28px;
  }
  svg { width: 100%; height: auto; display: block }
  button {
    display: block; margin: 12px auto 0;
    padding: 12px 20px; border: 0; border-radius: 8px;
    background: #1754c4; color: white;
    font: 600 15px Arial; cursor: pointer;
  }
</style>
<main id="slides"></main>
<script>
const tips = [
  ["Clear your", "desk"],
  ["Silence", "notifications"],
  ["Pick one", "task"],
  ["Set a", "timer"],
  ["Take a", "short break"]
];

const icons = [
  // Tidy desk
  `<path d="M-135 45H135M-110 45V130M110 45V130"/>
   <rect x="-75" y="-85" width="150" height="100" rx="10"/>
   <path d="M0 15V45M-30 45H30"/>
   <rect x="95" y="-20" width="35" height="65" rx="5"/>
   <path d="M104-20V-55M120-20V-65"/>`,

  // Muted bell
  `<path d="M-80 50H80L60 20V-35
   C60-110-60-110-60-35V20Z"/>
   <path d="M-22 80Q0 110 22 80M0-110V-130"/>
   <path d="M-125-125L125 125"
     stroke="white" stroke-width="28"/>
   <path d="M-125-125L125 125"/>`,

  // One checked task
  `<rect x="-100" y="-120" width="200" height="250" rx="18"/>
   <rect x="-55" y="-65" width="110" height="105" rx="12"
     fill="#e8f0ff"/>
   <path d="M-30-15L-7 8L35-38M-45 85H45"/>`,

  // Timer
  `<circle cx="0" cy="15" r="105"/>
   <path d="M-30-120H30M0-120V-90M75-65L95-85
   M0-60V15L45 45M-75 15H-65M65 15H75M0 80V90"/>`,

  // Short break
  `<path d="M-95-30H65V50Q65 110 5 110H-35
   Q-95 110-95 50Z"/>
   <path d="M65-10H90Q140-10 140 30
   Q140 70 65 70M-120 135H110"/>
   <path d="M-55-65Q-80-90-55-115
   M0-65Q-25-90 0-115M50-65Q25-90 50-115"/>`
];

tips.forEach((lines, i) => {
  const markup = `
  <svg xmlns="http://www.w3.org/2000/svg"
       width="1080" height="1350" viewBox="0 0 1080 1350">
    <rect width="1080" height="1350" fill="#ffffff"/>
    <rect x="64" y="64" width="952" height="1222"
          rx="32" fill="none" stroke="#dce7fa" stroke-width="3"/>
    <circle cx="155" cy="155" r="51" fill="#1754c4"/>
    <text x="155" y="174" text-anchor="middle"
          fill="white" font-family="Arial, sans-serif"
          font-size="52" font-weight="700">${i + 1}</text>
    <path d="M108 300H188" stroke="#1754c4"
          stroke-width="8" stroke-linecap="round"/>
    <text x="108" y="460" fill="#153c80"
          font-family="Arial, sans-serif"
          font-size="84" font-weight="700" letter-spacing="-2">
      <tspan x="108">${lines[0]}</tspan>
      <tspan x="108" dy="106">${lines[1]}</tspan>
    </text>
    <circle cx="540" cy="950" r="205" fill="#eff5ff"/>
    <g transform="translate(540 950)"
       fill="none" stroke="#1754c4" stroke-width="11"
       stroke-linecap="round" stroke-linejoin="round">
      ${icons[i]}
    </g>
  </svg>`;

  const card = document.createElement("section");
  card.innerHTML = markup;
  const button = document.createElement("button");
  button.textContent = `Download slide ${i + 1}`;
  button.onclick = () => {
    const blob = new Blob([markup], {type: "image/svg+xml"});
    const url = URL.createObjectURL(blob);
    const image = new Image();
    image.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = 1080;
      canvas.height = 1350;
      canvas.getContext("2d").drawImage(image, 0, 0);
      const link = document.createElement("a");
      link.download = `focus-tip-${i + 1}.png`;
      link.href = canvas.toDataURL("image/png");
      link.click();
      URL.revokeObjectURL(url);
    };
    image.src = url;
  };
  card.appendChild(button);
  document.getElementById("slides").appendChild(card);
});
</script>
</html>
```

